interface UserPreferences {
  theme: string;
  language: string;
  notifications: boolean;
  lastUpdated: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  const res = await fetch('http://localhost:3000/api/user/preferences', {
    cache: 'no-store', // Disable caching to fetch fresh data on each request
    headers: {
      'Cache-Control': 'no-cache',
    },
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h3>User Preferences</h3>
        <p><strong>Theme:</strong> {preferences.theme}</p>
        <p><strong>Language:</strong> {preferences.language}</p>
        <p><strong>Notifications:</strong> {preferences.notifications ? 'Enabled' : 'Disabled'}</p>
        <p><strong>Last Updated:</strong> {new Date(preferences.lastUpdated).toLocaleString()}</p>
        <p style={{ fontSize: '12px', color: '#666', marginTop: '10px' }}>
          This data is fetched fresh on each request (no caching).
        </p>
      </div>
    </div>
  );
}

